374	// validateLoaded 对解码后的状态做基本不变量检查，违背即视为损坏。
375	func validateLoaded(fd *fileData) error {
376		switch {
377		case fd.Version != int(fileVersion):
378			return fmt.Errorf("%w: version %d in payload", ErrUnsupportedVersion, fd.Version)
379		case len(fd.Trajectory) == 0:
380			return fmt.Errorf("%w: empty trajectory", ErrCorrupt)
381		}
382		if err := validateConfig(fd.Config); err != nil {
383			// 配置不合法不可能由本版本写出。
384			return fmt.Errorf("%w: %v", ErrCorrupt, err)
385		}
386		// 保存的整条轨迹必须满足与导入时相同的时间规则：从初始位姿起
387		// 时间严格递增，且相邻位姿的真实间隔不超过 MaxInterval（恰好
388		// 等于上限合法）。任何一处相等、倒退或超限都使按时间查询失去
389		// 可靠的先后依据，整份文件按损坏拒绝。间隔按真实差值判断：前
390		// 一时间接近 math.MinInt64 而后一时间为非负时，有符号减法会
391		// 溢出回绕成负数，把超限的巨大缺口放过去；此处已保证递增，真
392		// 实差值落在 [1, 2^64-1]，用无符号减法取精确的数学差值再与上
393		// 限比较（MaxInterval 已校验为正）。
394		for i := 1; i < len(fd.Trajectory); i++ {
395			prev, cur := fd.Trajectory[i-1].Time, fd.Trajectory[i].Time
396			if cur <= prev {
397				return fmt.Errorf("%w: trajectory time at pose %d is not strictly increasing", ErrCorrupt, i)
398			}
399			if uint64(cur)-uint64(prev) > uint64(fd.Config.MaxInterval) {
400				return fmt.Errorf("%w: trajectory interval between poses %d and %d exceeds max interval", ErrCorrupt, i-1, i)
401			}
402		}
403		// 新格式的逐帧依据必须与轨迹（除初始位姿外）一一对应；旧文件缺省
404		// 该字段（解码为 nil），数量为 0。
405		if len(fd.Sources) != 0 && len(fd.Sources) != len(fd.Trajectory)-1 {
406			return fmt.Errorf("%w: frame sources length %d for %d frames", ErrCorrupt, len(fd.Sources), len(fd.Trajectory)-1)
407		}
408		seenIDs := make(map[string]struct{}, len(fd.Landmarks))
409		for _, lm := range fd.Landmarks {
410			if lm.ID == "" {
411				return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
412			}
413			if _, dup := seenIDs[lm.ID]; dup {
414				return fmt.Errorf("%w: duplicate landmark %s", ErrCorrupt, lm.ID)
415			}
416			seenIDs[lm.ID] = struct{}{}
417			if len(lm.Occurrences) == 0 {
418				// 兼容旧布局：平铺字段表示第 1 次出现。
419				if lm.Count < 1 || !isFinite(lm.X) || !isFinite(lm.Y) {
420					return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
421				}
422				if lm.LegacyCount < 0 || lm.LegacyCount > lm.Count {
423					return fmt.Errorf("%w: invalid legacy count for landmark %s", ErrCorrupt, lm.ID)
424				}
425				if lm.LegacyCount > 0 && (!isFinite(lm.LegacyMX) || !isFinite(lm.LegacyMY)) {
426					return fmt.Errorf("%w: invalid legacy mean for landmark %s", ErrCorrupt, lm.ID)
427				}
428				continue
429			}
430			activeCount := 0
431			for i, oj := range lm.Occurrences {
432				if oj.Number != i+1 || oj.Count < 1 || !isFinite(oj.X) || !isFinite(oj.Y) {
433					return fmt.Errorf("%w: invalid occurrence for landmark %s", ErrCorrupt, lm.ID)
434				}
435				if oj.LegacyCount < 0 || oj.LegacyCount > oj.Count {
436					return fmt.Errorf("%w: invalid legacy count for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
437				}
438				if oj.LegacyCount > 0 && (!isFinite(oj.LegacyMX) || !isFinite(oj.LegacyMY)) {
439					return fmt.Errorf("%w: invalid legacy mean for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
440				}
441				if oj.Active {
442					activeCount++
443					if i != len(lm.Occurrences)-1 {
444						return fmt.Errorf("%w: active occurrence %d of landmark %s is not the latest", ErrCorrupt, oj.Number, lm.ID)
445					}
446				} else if oj.InvalidReason == "" {
447					return fmt.Errorf("%w: invalidated occurrence %d of landmark %s lacks reason", ErrCorrupt, oj.Number, lm.ID)
448				}
449				// 出现编号即先后次序，各次出现接纳观测的时间范围必须与之
450				// 相容，否则同一观测可能同时属于两次出现（归属校验只确认能
451				// 归入某一次，不排除同时归入两次）。已失效且首次观测时间
452				// 已知的出现，首次观测不能晚于失效；下一次出现的首次观测
453				// 必须严格晚于上一次的失效时间——首次观测与失效两个端点都
454				// 接纳所在时刻的观测，相等即重叠。第 2 次及以后的出现必定
455				// 在上一次失效之后由本包创建，首次观测时间必须已知；只有
456				// 旧文件的第 1 次出现允许未知（无下界，不把零当作起点）。
457				// 这些检查针对保存的出现记录本身，与重叠范围内当前是否有
458				// 观测无关。
459				if !oj.Active && oj.HasFirstSeen && oj.FirstSeenTime > oj.InvalidTime {
460					return fmt.Errorf("%w: occurrence %d of landmark %s first seen at %d after invalidation at %d", ErrCorrupt, oj.Number, lm.ID, oj.FirstSeenTime, oj.InvalidTime)
461				}
462				if i > 0 {
463					if !oj.HasFirstSeen {
464						return fmt.Errorf("%w: occurrence %d of landmark %s lacks first seen time", ErrCorrupt, oj.Number, lm.ID)
465					}
466					// 上一次出现必已失效（仍有效且非最后一次已在上面拒绝）。
467					if prev := lm.Occurrences[i-1]; oj.FirstSeenTime <= prev.InvalidTime {
468						return fmt.Errorf("%w: occurrence %d of landmark %s starts at %d before previous invalidation at %d", ErrCorrupt, oj.Number, lm.ID, oj.FirstSeenTime, prev.InvalidTime)
469					}
470				}
471			}
472			if activeCount > 1 {
473				return fmt.Errorf("%w: multiple active occurrences for landmark %s", ErrCorrupt, lm.ID)
474			}
475		}
476		// 校验每条带逐帧依据的观测来源：观测路标必须存在，且所在帧时间必须
477		// 落入该路标某一次出现的时间边界（共享规则见 occurrence.go）。旧出现
478		// 已失效不代表其历史观测无效；同一标识两次出现之间（如 200 失效、
479		// 300 再现时的 250 帧）的观测没有归属，按损坏拒绝。null 帧来自缺少
480		// 逐帧依据的旧地图，其观测不在这里（也无法）核验；旧版平铺路标视为
481		// 一次无边界的有效出现，因此旧地图后来追加的来源帧仍按此规则检查。
482		if len(fd.Sources) != 0 {
483			bounds := make(map[string][]occurrenceWindow, len(fd.Landmarks))
484			for _, lm := range fd.Landmarks {
485				bounds[lm.ID] = occurrenceWindowsOf(lm)
486			}
487			// 归属校验的同时按（路标，出现编号）统计来源观测条数：每条观测
488			// 各算一次，同帧重复观测同一标识不去重，空观测帧不计。null 帧
489			// 缺少逐帧依据，其贡献已固定在出现的旧观测计数中，不在此统计，
490			// 也不能按帧数猜测。
491			tallies := make(map[string]map[int]int, len(fd.Landmarks))
492			for k, src := range fd.Sources {
493				if src == nil {
494					continue // 旧地图帧：无逐帧依据，不要求补齐归属
495				}
496				t := fd.Trajectory[k+1].Time
497				for _, ob := range src.Observations {
498					wins, ok := bounds[ob.ID]
499					if !ok {
500						return fmt.Errorf("%w: observation of unknown landmark %s at frame time %d", ErrCorrupt, ob.ID, t)
501					}
502					num := occurrenceNumberAt(wins, t)
503					if num == 0 {
504						return fmt.Errorf("%w: observation of landmark %s at frame time %d belongs to no occurrence", ErrCorrupt, ob.ID, t)
505					}
506					c := tallies[ob.ID]
507					if c == nil {
508						c = make(map[int]int, 1)
509						tallies[ob.ID] = c
510					}
511					c[num]++
512				}
513			}
514			// 每次出现记录的观测次数必须等于归属该次出现的来源观测条数加上
515			// 该次出现已保存的旧观测贡献：偏多或偏少都是文件损坏。各次出现
516			// 分别核对，不能用另一次出现的观测补足；已失效的旧出现同样核对，
517			// 不因它不再参与区域查询而跳过。回环校正只改位置不改已接受观测
518			// 次数，正常校正后保存的文件仍满足此不变量。
519			for _, lm := range fd.Landmarks {
520				if len(lm.Occurrences) == 0 {
521					// 旧版平铺路标即第 1 次出现。
522					if got := tallies[lm.ID][1] + lm.LegacyCount; got != lm.Count {
523						return fmt.Errorf("%w: landmark %s records %d observations but sources and legacy contributions account for %d", ErrCorrupt, lm.ID, lm.Count, got)
524					}
525					continue
526				}
527				for _, oj := range lm.Occurrences {
528					if got := tallies[lm.ID][oj.Number] + oj.LegacyCount; got != oj.Count {
529						return fmt.Errorf("%w: landmark %s occurrence %d records %d observations but sources and legacy contributions account for %d", ErrCorrupt, lm.ID, oj.Number, oj.Count, got)
530					}
531				}
532			}
533		}
534		segIDs := make(map[string]struct{}, len(fd.Segments))
535		for _, sg := range fd.Segments {
536			if sg.ID == "" || sg.Hash == "" {
537				return fmt.Errorf("%w: invalid segment record", ErrCorrupt)
538			}
539			if _, dup := segIDs[sg.ID]; dup {
540				return fmt.Errorf("%w: duplicate segment %s", ErrCorrupt, sg.ID)
541			}
542			segIDs[sg.ID] = struct{}{}
543		}
544		corrIDs := make(map[string]struct{}, len(fd.Corrections))
545		for _, cr := range fd.Corrections {
546			if cr.ID == "" || cr.Anchor > cr.EndTime {
547				return fmt.Errorf("%w: invalid correction record", ErrCorrupt)
548			}
549			// 锚点与结束时间必须准确命中已导入帧：trajectory[0] 是初始位姿，
550			// 不是可校正的帧，也不能用相邻帧的时间代替。轨迹时间已在前面
551			// 校验为严格递增，命中即唯一。
552			anchorIdx, endIdx := -1, -1
553			for j := 1; j < len(fd.Trajectory); j++ {
554				if fd.Trajectory[j].Time == cr.Anchor {
555					anchorIdx = j
556				}
557				if fd.Trajectory[j].Time == cr.EndTime {
558					endIdx = j
559				}
560			}
561			if anchorIdx < 0 || endIdx < 0 {
562				return fmt.Errorf("%w: correction %s range does not hit imported frames", ErrCorrupt, cr.ID)
563			}
564			// 记录必须恰好覆盖 [anchor, end] 内的每一帧：位姿条目数量等于
565			// 范围内帧数，按轨迹时间次序一一对应，且同一份前后位姿的时间
566			// 相同并就是对应帧的时间。缺失、重复、错序、额外加入范围外的
567			// 帧，或把前后时间写成两个不同帧，都使记录不能完整描述声明的
568			// 范围，按损坏拒绝。这里只核对覆盖的帧及时间：快照中的位置、
569			// 朝向和方差是提交时的历史值，不要求等于当前轨迹（后来对相同
570			// 范围再校正、或之后导入新帧，都不影响既有记录的合法性）。
571			if len(cr.Poses) != endIdx-anchorIdx+1 {
572				return fmt.Errorf("%w: correction %s does not cover every frame in its range", ErrCorrupt, cr.ID)
573			}
574			for i, pc := range cr.Poses {
575				ft := fd.Trajectory[anchorIdx+i].Time
576				if pc.Before.Time != ft || pc.After.Time != ft {
577					return fmt.Errorf("%w: correction %s pose entry %d does not match frame time %d", ErrCorrupt, cr.ID, i, ft)
578				}
579				if !finitePose(pc.Before) || !finitePose(pc.After) {
580					return fmt.Errorf("%w: correction %s has non-finite pose", ErrCorrupt, cr.ID)
581				}
582			}
583			for _, lc := range cr.Landmarks {
584				if lc.ID == "" {
585					return fmt.Errorf("%w: correction %s has empty landmark id", ErrCorrupt, cr.ID)
586				}
587				if lc.Occurrence < 0 || !isFinite(lc.Before.X) || !isFinite(lc.Before.Y) ||
588					!isFinite(lc.After.X) || !isFinite(lc.After.Y) ||
589					lc.Before.Count < 1 || lc.After.Count < 1 {
590					return fmt.Errorf("%w: correction %s has invalid landmark change", ErrCorrupt, cr.ID)
591				}
592			}
593			if _, dup := corrIDs[cr.ID]; dup {
594				return fmt.Errorf("%w: duplicate correction %s", ErrCorrupt, cr.ID)
595			}
596			corrIDs[cr.ID] = struct{}{}
597		}
598		invalIDs := make(map[string]struct{}, len(fd.Invalidations))
599		for _, iv := range fd.Invalidations {
600			if iv.ID == "" || iv.Reason == "" || iv.Hash == "" || len(iv.Landmarks) == 0 {
601				return fmt.Errorf("%w: invalid invalidation record", ErrCorrupt)
602			}
603			if _, dup := invalIDs[iv.ID]; dup {
604				return fmt.Errorf("%w: duplicate invalidation %s", ErrCorrupt, iv.ID)
605			}
606			invalIDs[iv.ID] = struct{}{}
607			lmSeen := make(map[string]struct{}, len(iv.Landmarks))
608			for _, l := range iv.Landmarks {
609				if l.ID == "" || l.Occurrence < 1 {
610					return fmt.Errorf("%w: invalid invalidation landmark entry", ErrCorrupt)
611				}
612				if _, dup := lmSeen[l.ID]; dup {
613					return fmt.Errorf("%w: invalidation %s lists %s twice", ErrCorrupt, iv.ID, l.ID)
614				}
615				lmSeen[l.ID] = struct{}{}
616			}
617		}
618		return nil
619	}
620	
621	func finitePose(p Pose) bool {
622		return isFinite(p.X) && isFinite(p.Y) && isFinite(p.Heading) && isFinite(p.Variance)
623	}
624	
625	// canonicalCorrectionHash 计算一次校正请求（锚点时间 + 目标位姿）的
626	// 确定性指纹，用于同标识重复提交判定。直接按 IEEE-754 位编码。
627	func canonicalCorrectionHash(anchor int64, tgt CorrectionTarget) string {
628		h := sha256.New()
629		var b [8]byte
630		binary.BigEndian.PutUint64(b[:], uint64(anchor))
631		h.Write(b[:])
632		for _, v := range []float64{tgt.X, tgt.Y, tgt.Heading, tgt.Variance} {
633			binary.BigEndian.PutUint64(b[:], math.Float64bits(v))
634			h.Write(b[:])
635		}
636		return fmt.Sprintf("%x", h.Sum(nil))
637	}
638	
639	// saveExclusive 创建新文件，目标已存在即失败（O_EXCL）。
640	func (m *Map) saveExclusive() error {
641		data, err := encodeFile(m.state)
642		if err != nil {
643			return err
644		}
645		f, err := os.OpenFile(m.path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
646		if err != nil {
647			return err
648		}
649		return writeAndClose(f, data, m.path)
650	}
651	
652	// saveReplace 用同目录临时文件 + rename 原子替换现有文件。
653	func (m *Map) saveReplace() (err error) {
654		data, err := encodeFile(m.state)
655		if err != nil {
656			return err
657		}
658		dir, base := filepath.Split(m.path)
659		if dir == "" {
660			dir = "."
661		}
662		f, err := os.CreateTemp(dir, base+".tmp-*")
663		if err != nil {
664			return err
665		}
666		tmpName := f.Name()
667		// 任何失败路径都尽力清理临时文件。
668		defer func() {
669			if err != nil {
670				_ = os.Remove(tmpName)
671			}
672		}()
673		if err = writeAndClose(f, data, tmpName); err != nil {
674			return err
675		}
676		if err = os.Rename(tmpName, m.path); err != nil {
677			return err
678		}
679		return nil
680	}
681	
682	func writeAndClose(f *os.File, data []byte, name string) (err error) {
683		defer func() {
684			if cerr := f.Close(); err == nil {
685				err = cerr
686			}
687		}()
688		if _, err = f.Write(data); err != nil {
689			return err
690		}
691		if err = f.Sync(); err != nil {
692			return err
693		}
694		return nil
695	}
696	
697	// canonicalHash 计算一批帧的确定性指纹，用于重复导入判定。直接按
698	// IEEE-754 位编码，NaN/Inf 也有稳定表示，不依赖 JSON 对其不支持的问题。
699	func canonicalHash(frames []Frame) string {
700		h := sha256.New()
701		var lenBuf [4]byte
702		var numBuf [8]byte
703		putU32 := func(v uint32) {
704			binary.BigEndian.PutUint32(lenBuf[:], v)
705			h.Write(lenBuf[:])
706		}
707		putU64 := func(v uint64) {
708			binary.BigEndian.PutUint64(numBuf[:], v)
709			h.Write(numBuf[:])
710		}
711		putStr := func(s string) {
712			putU32(uint32(len(s)))
713			h.Write([]byte(s))
714		}
715	
716		putU32(uint32(len(frames)))
717		for _, fr := range frames {
718			putU64(uint64(fr.Time))
719			putU64(math.Float64bits(fr.DX))
720			putU64(math.Float64bits(fr.DY))
721			putU64(math.Float64bits(fr.DHeading))
722			putU64(math.Float64bits(fr.MoveVariance))
723			putU32(uint32(len(fr.Observations)))
724			for _, ob := range fr.Observations {
725				putStr(ob.ID)
726				putU64(math.Float64bits(ob.X))
727				putU64(math.Float64bits(ob.Y))
728			}
729		}
730		return fmt.Sprintf("%x", h.Sum(nil))
731	}
732

