1	package posemap
2	
3	import (
4		"math"
5		"path/filepath"
6		"testing"
7	)
8	
9	// 大数值坐标下求路标平均位置不得溢出：两次 (1e308, 0) 观测应保存为
10	// (1e308, 0)、次数 2，而不是因中间计算得到无穷而拒绝。
11	func TestImportHugeCoordinateMean(t *testing.T) {
12		path := filepath.Join(t.TempDir(), "map.bin")
13		m, err := Create(path, Config{
14			InitialTime: 1000, MaxInterval: 100, MergeDistance: 10,
15		})
16		if err != nil {
17			t.Fatalf("Create: %v", err)
18		}
19		defer m.Close()
20	
21		obs := []Observation{{ID: "L", X: 1e308, Y: 0}}
22		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
23			{Time: 1001, Observations: obs},
24			{Time: 1002, Observations: obs},
25		}}); err != nil {
26			t.Fatalf("ImportSegment: %v", err)
27		}
28		lms, err := m.LandmarksInRect(Rect{MinX: 0, MinY: -1, MaxX: math.MaxFloat64, MaxY: 1})
29		if err != nil {
30			t.Fatalf("LandmarksInRect: %v", err)
31		}
32		if len(lms) != 1 {
33			t.Fatalf("want 1 landmark, got %d", len(lms))
34		}
35		if lms[0].X != 1e308 || lms[0].Y != 0 || lms[0].Count != 2 {
36			t.Fatalf("got %+v, want X=1e308 Y=0 Count=2", lms[0])
37		}
38	
39		// 关闭重开后结果一致。
40		if err := m.Close(); err != nil {
41			t.Fatalf("Close: %v", err)
42		}
43		m2, err := Open(path)
44		if err != nil {
45			t.Fatalf("Open: %v", err)
46		}
47		defer m2.Close()
48		lms2, err := m2.LandmarksInRect(Rect{MinX: 0, MinY: -1, MaxX: math.MaxFloat64, MaxY: 1})
49		if err != nil {
50			t.Fatalf("LandmarksInRect after reopen: %v", err)
51		}
52		if len(lms2) != 1 || lms2[0].X != 1e308 || lms2[0].Count != 2 {
53			t.Fatalf("after reopen got %+v", lms2)
54		}
55	}
56	
57	// 混合大数值观测按等权平均：两次 (8e307, 0) 加一次 (1e308, 0)，合并距离
58	// 3e307，三次都接受，均值约 8.666666666666667e307、次数 3，且结果有限并
59	// 落在参与平均的坐标范围内。纵坐标与负数坐标遵守同一规则。
60	func TestImportHugeCoordinateWeightedMean(t *testing.T) {
61		path := filepath.Join(t.TempDir(), "map.bin")
62		m, err := Create(path, Config{
63			InitialTime: 1000, MaxInterval: 100, MergeDistance: 3e307,
64		})
65		if err != nil {
66			t.Fatalf("Create: %v", err)
67		}
68		defer m.Close()
69	
70		if _, err := m.ImportSegment(Segment{ID: "s1", Frames: []Frame{
71			{Time: 1001, Observations: []Observation{
72				{ID: "L", X: 8e307, Y: 0},
73				{ID: "L", X: 8e307, Y: 0},
74				{ID: "L", X: 1e308, Y: 0},
75				{ID: "N", X: -8e307, Y: 1e308},
76				{ID: "N", X: -8e307, Y: 1e308},
77				{ID: "N", X: -1e308, Y: 8e307},
78			}},
79		}}); err != nil {
80			t.Fatalf("ImportSegment: %v", err)
81		}
82		lms, err := m.LandmarksInRect(Rect{MinX: -math.MaxFloat64, MinY: -math.MaxFloat64, MaxX: math.MaxFloat64, MaxY: math.MaxFloat64})
83		if err != nil {
84			t.Fatalf("LandmarksInRect: %v", err)
85		}
86		if len(lms) != 2 {
87			t.Fatalf("want 2 landmarks, got %d", len(lms))
88		}
89		want := 8e307 + (1e308-8e307)/3 // 8.666666666666667e307
90		for _, lm := range lms {
91			if lm.Count != 3 {
92				t.Fatalf("%s: count = %d, want 3", lm.ID, lm.Count)
93			}
94			if !isFinite(lm.X) || !isFinite(lm.Y) {
95				t.Fatalf("%s: non-finite position %+v", lm.ID, lm)
96			}
97		}
98		if math.Abs(lms[0].X-want) > math.Abs(want)*1e-12 || lms[0].X < 8e307 || lms[0].X > 1e308 {
99			t.Fatalf("L.X = %v, want ~%v within [8e307, 1e308]", lms[0].X, want)
100		}
101		if lms[0].ID != "L" || lms[1].ID != "N" {
102			t.Fatalf("unexpected ids: %+v", lms)
103		}
104		if math.Abs(lms[1].X+want) > math.Abs(want)*1e-12 || lms[1].X > -8e307 || lms[1].X < -1e308 {
105			t.Fatalf("N.X = %v, want ~%v", lms[1].X, -want)
106		}
107		wantY := 1e308 + (8e307-1e308)/3 // 9.333333333333333e307
108		if math.Abs(lms[1].Y-wantY) > math.Abs(wantY)*1e-12 || lms[1].Y < 8e307 || lms[1].Y > 1e308 {
109			t.Fatalf("N.Y = %v, want ~%v", lms[1].Y, wantY)
110		}
