240	
241	// assertUnchangedAfterRejectedOrderB 校验次序 B 地图在校正被整体拒绝后
242	// 没有任何部分更新：同帧前一条已暂时接纳的观测没有改变路标位置或次数，
243	// 位姿与既有校正记录也保持提交前结果。
244	func assertUnchangedAfterRejectedOrderB(t *testing.T, m *Map) {
245		t.Helper()
246		lms, _ := m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
247		if len(lms) != 1 || lms[0].ID != "L" {
248			t.Fatalf("landmarks after reject = %v", lms)
249		}
250		approxEq(t, "L x unchanged", lms[0].X, -0.2)
251		approxEq(t, "L y unchanged", lms[0].Y, 0)
252		if lms[0].Count != 5 {
253			t.Fatalf("L count after reject = %d, want 5 (tentative admission leaked)", lms[0].Count)
254		}
255		h, err := m.LandmarkAppearances("L")
256		if err != nil {
257			t.Fatal(err)
258		}
259		if len(h.Appearances) != 1 || !h.Appearances[0].Active {
260			t.Fatalf("appearances after reject = %+v", h.Appearances)
261		}
262		approxEq(t, "appearance x unchanged", h.Appearances[0].Landmark.X, -0.2)
263		if h.Appearances[0].Landmark.Count != 5 {
264			t.Fatalf("appearance count after reject = %d", h.Appearances[0].Landmark.Count)
265		}
266		for _, tc := range []struct {
267			time         int64
268			wantX        float64
269			wantHeading  float64
270			wantVariance float64
271		}{
272			{0, 0, 0, 0.5},
273			{50, 0, 0, 0.6},
274			{100, 0, 0, 0.7},
275			{200, 0, 0, 0.8},
276		} {
277			p, err := m.PoseAt(tc.time)
278			if err != nil {
279				t.Fatalf("PoseAt(%d): %v", tc.time, err)
280			}
281			if p.X != tc.wantX || p.Heading != tc.wantHeading || math.Abs(p.Variance-tc.wantVariance) > 1e-12 {
282				t.Fatalf("PoseAt(%d) = %+v, want X=%v heading=%v variance=%v",
283					tc.time, p, tc.wantX, tc.wantHeading, tc.wantVariance)
284			}
285		}
286		// 同标识校正可再次提交（冲突的那次没有消耗校正标识、没有落记录）。
287		if recs, _ := m.Corrections(); len(recs) != 0 {
288			t.Fatalf("correction records after reject = %v, want none", recs)
289		}
290	}
291	
292	// 同帧内前一条已被接纳、后一条才发生冲突：冲突观测之前的同帧第一条
293	// 观测（与固定观测距离恰好等于合并上限）已在暂存聚合中接纳，但整次
294	// 校正仍必须失败且不留任何部分更新。错误指出实际冲突帧时间、路标
295	// 标识与所属出现编号。
296	func TestCorrectionSameFrameConflictAfterTentativeAdmission(t *testing.T) {
297		cfg := sameFrameConfig()
298		m := newMap(t, cfg)
299		// t=50：对 L 的固定观测，世界 X=0。
300		// t=100：同帧两条 L 观测，本地 X 依次为 0、+1（导入时世界 X 为
301		// 0、+1：第一条与固定观测重合，第二条距当时均值 0.5 恰在限内，
302		// 两条都合法）。
303		if _, err := m.ImportSegment(Segment{
304			ID: "seg",
305			Frames: []Frame{
306				{Time: 50, DX: 0, MoveVariance: 0.1,
307					Observations: []Observation{{ID: "L", X: 0, Y: 0}}},
308				{Time: 100, DX: 0, MoveVariance: 0.1,
309					Observations: []Observation{{ID: "L", X: 0, Y: 0}, {ID: "L", X: 1, Y: 0}}},
310			},
311		}); err != nil {
312			t.Fatalf("import: %v", err)
313		}
314		// 校正前 L 为 (0,0,+1)/3 即 X=1/3，计数 3。
315		lms, _ := m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
316		if len(lms) != 1 {
317			t.Fatalf("landmarks = %v", lms)
318		}
319		approxEq(t, "L x before", lms[0].X, 1.0/3.0)
320		if lms[0].Count != 3 {
321			t.Fatalf("L count before = %d, want 3", lms[0].Count)
322		}
323	
324		// 只平移不旋转 +1：锚点帧第一条世界 X=1，与固定观测 0 的距离恰好
325		// 等于合并上限 1 → 暂纳（均值变为 0.5、计数 2）；第二条世界 X=2，
326		// 与新均值 0.5 相距 1.5 > 1 → 冲突。
327		_, err := m.Correct(Correction{
328			ID:     "c-conflict",
329			Anchor: 100,
330			Target: CorrectionTarget{X: 1, Y: 0, Heading: 0, Variance: 0},
331		})
332		r, ok := AsRejectError(err)
333		if !ok {
334			t.Fatalf("err = %v, want *RejectError", err)
335		}
336		if r.Kind != RejectLandmarkConflict || !r.HasTime || r.Time != 100 ||
337			!r.HasLandmark || r.Landmark != "L" || !r.HasOccurrence || r.Occurrence != 1 {
338			t.Fatalf("reject = %+v, want landmark_conflict at time 100 L occurrence 1", r)
339		}
340	
341		// 整次校正不生效：第一条已暂纳的观测没有改变路标位置或次数。
342		lms, _ = m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
343		if len(lms) != 1 {
344			t.Fatalf("landmarks after conflict = %v", lms)
345		}
346		approxEq(t, "L x after conflict", lms[0].X, 1.0/3.0)
347		if lms[0].Count != 3 {
348			t.Fatalf("L count after conflict = %d, want 3 (tentative admission leaked)", lms[0].Count)
349		}
350		h, _ := m.LandmarkAppearances("L")
351		if len(h.Appearances) != 1 || !h.Appearances[0].Active {
352			t.Fatalf("appearances after conflict = %+v", h.Appearances)
353		}
354		approxEq(t, "appearance x after conflict", h.Appearances[0].Landmark.X, 1.0/3.0)
355		if h.Appearances[0].Landmark.Count != 3 {
356			t.Fatalf("appearance count after conflict = %d", h.Appearances[0].Landmark.Count)
357		}
358		// 位姿保持提交前结果。
359		cur, _ := m.CurrentPose()
360		if cur.Time != 100 || cur.X != 0 || cur.Heading != 0 {
361			t.Fatalf("current pose after conflict = %+v", cur)
362		}
363		approxEq(t, "current variance after conflict", cur.Variance, 0.7)
364		// 既有校正记录保持提交前结果（无记录）。
365		if recs, _ := m.Corrections(); len(recs) != 0 {
366			t.Fatalf("correction records after conflict = %v, want none", recs)
367		}
368	
369		// 同一张图把平移改成恰好可接纳（0 平移的恒等位置校正）后可成功，
370		// 证明被拒完全源于同帧逐条次序而非观测或轨迹本身。
371		rec, err := m.Correct(Correction{
372			ID:     "c-conflict",
373			Anchor: 100,
374			Target: CorrectionTarget{X: 0, Y: 0, Heading: 0, Variance: 0},
375		})
376		if err != nil {
377			t.Fatalf("identity correction after conflict: %v", err)
378		}
379		if len(rec.Landmarks) != 1 || rec.Landmarks[0].After.Count != 3 {
380			t.Fatalf("identity record = %+v", rec.Landmarks)
381		}
382		approxEq(t, "L x after identity", rec.Landmarks[0].After.X, 1.0/3.0)
383	}
384

