// 完全没有逐帧观测依据的纯旧文件不核对位置：篡改保存位置后仍按现有规则
// 打开，不要求补造观测。
func TestOpenPureLegacyFileSkipsPositionCheck(t *testing.T) {
	path := filepath.Join(t.TempDir(), "m.pose")
	cfg := Config{InitialTime: 0, MaxInterval: 1000, MergeDistance: 1.0}
